package android.database;
import java.sql.*;
public class Cursor { private final ResultSet rs; private final Statement st; public Cursor(ResultSet r,Statement s){rs=r;st=s;} boolean positioned=false; public boolean moveToFirst(){try{positioned=rs.next();return positioned;}catch(SQLException e){throw new RuntimeException(e);}} public boolean moveToNext(){try{if(!positioned)return moveToFirst();positioned=rs.next();return positioned;}catch(SQLException e){throw new RuntimeException(e);}} public long getLong(int i){try{return rs.getLong(i+1);}catch(SQLException e){throw new RuntimeException(e);}} public int getInt(int i){try{return rs.getInt(i+1);}catch(SQLException e){throw new RuntimeException(e);}} public String getString(int i){try{return rs.getString(i+1);}catch(SQLException e){throw new RuntimeException(e);}} public void close(){try{rs.close();st.close();}catch(SQLException e){throw new RuntimeException(e);}} }
